'use client';

/**
 * Visitor Google OAuth callback.
 * Generated by @egdesk/next-api-plugin — do not edit.
 */

import { useEffect, useState } from 'react';
import { exchangeVisitorAuthCode, getVisitorGoogleStatus, resolveVisitorAppPath } from '@/egdesk-visitor-google';
import { apiFetch } from '@/egdesk-helpers';

const processedCallbackCodes = new Set<string>();

export default function VisitorAuthCallbackPage() {
  const [message, setMessage] = useState('Google 계정을 연동하는 중입니다…');

  useEffect(() => {
    const params = new URLSearchParams(window.location.search);
    const code = (params.get('code') || '').trim();
    const next = params.get('next') || '/dashboard';
    if (!code) {
      setMessage('Missing login code. Close this page and try Sign in with Google again.');
      return;
    }
    if (processedCallbackCodes.has(code)) {
      return;
    }
    processedCallbackCodes.add(code);

    let finished = false;
    const timer = window.setTimeout(() => {
      if (finished) return;
      finished = true;
      setMessage('Sign-in timed out. Close this page and try Sign in with Google again.');
    }, 20000);
    void exchangeVisitorAuthCode(code)
      .then(async (exRes) => {
        try {
          const sid = exRes?.sessionId || window.localStorage.getItem('egdesk_visitor_session') || '';
          const status = await getVisitorGoogleStatus().catch(() => null);
          if (status?.connected && status?.email && sid) {
            await apiFetch('/api/auth/google/session', {
              method: 'POST',
              headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify({
                email: status.email,
                name: status.name || status.email.split('@')[0],
                visitorSessionId: sid,
              }),
            }).catch(() => {});
            window.sessionStorage.setItem('sheetbot_session_synced', sid);
            window.localStorage.setItem('sheetbot_synced_visitor_sid', sid);
          }
        } catch {}
        if (finished) return;
        finished = true;
        window.clearTimeout(timer);
        const dest = resolveVisitorAppPath(next.startsWith('/') ? next : '/dashboard');
        window.location.replace(dest);
      })
      .catch((err: unknown) => {
        processedCallbackCodes.delete(code);
        if (finished) return;
        finished = true;
        window.clearTimeout(timer);
        const text = err instanceof Error ? err.message : String(err);
        setMessage('Sign-in failed: ' + text);
      });
    return () => window.clearTimeout(timer);
  }, []);

  return (
    <main style={{ fontFamily: 'system-ui, sans-serif', padding: 24 }}>
      <p>{message}</p>
    </main>
  );
}
